CREATE TABLE `survey_form_versions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `form_id` int NOT NULL,
  `number` int NOT NULL,
  `revision` int NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `language` varchar(10) NOT NULL,
  `status` varchar(20) NOT NULL,
  `starts_at` datetime DEFAULT NULL,
  `ends_at` datetime DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `reporting_start` date DEFAULT NULL,
  `reporting_end` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `form_id` (`form_id`,`number`),
  KEY `ix_survey_form_versions_status` (`status`),
  KEY `ix_survey_form_versions_form_id` (`form_id`),
  CONSTRAINT `survey_form_versions_ibfk_1` FOREIGN KEY (`form_id`) REFERENCES `survey_forms` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
