INSERT INTO `survey_workbook_answers` VALUES (1,1,'1','မွေးထုတ်ပေးသည့် IT ဘွဲ့ရ ကျောင်းသားဦးရေ (၂၀၁၀ ခုနှစ် မှ ၂၀၁၅ ခုနှစ်၊ မတ်လထိ) (Bachelor ဘွဲ့/ Master ဘွဲ့/ Ph.D ဘွဲ့/  Diploma ဘွဲ့ စသည်ဖြင့်  ခွဲခြားဖော်ပြရန်)','B6','','','B.C.Sc.= 210\nB.C.Tech. = 39\nB.C.Sc.(Hon:) = 86\nB.C.Tech.(Hon:) = 16\nM.C.Sc.= 23\nM.C.Tech. = 3',''),(2,1,'2','ဒီဂျစ်တယ်ကျွမ်းကျင်မှု သင်တန်းများဖွင့်လှစ်ပေးနိုင်မှုအခြေအနေ','B7','ရှိ','','261',''),(3,1,'3','ဒီဂျစ်တယ်ကျွမ်းကျင်မှု သက်မွေးပညာ လေ့ကျင့်ရေး အစီအစဉ်များတွင် ပါဝင်သည့်သင်တန်းသား အရေအတွက်။ (Certificate သင်တန်းများ)','B8','ရှိ','','261','ကွန်ပျူတာအသုံးချ\nသင်တန်း'),(4,1,'4','ဒီဂျစ်တယ်စီးပွားရေးလုပ်ငန်းများတွင် အလုပ်အကိုင်ရရှိမှု အရေအတွက်','B9','','','ကောက်ခံနိုင်ခဲ့ခြင်းမရှိပါ',''),(5,1,'5','ဆရာ၊ဆရာမများအား ဒီဂျစ်တယ်ပညာရပ်နှင့် နည်းပညာဘာသာရပ် သင်ကြားမှုစွမ်းရည်အတွက် Capacity Building သင်တန်းများ သင်ကြားပေးနိုင်မှုအခြေအနေ','B10','','','2\n(SPSS, LMS)',''),(6,1,'6','ပြည်သူများအကြား ဒီဂျစ်တယ်တတ်မြောက်မှု မြှင့်တင်ရန် အသိပညာပေး ဆောင်ရွက်မှုများ','B11','','','',''),(7,1,'7','တက္ကသိုလ်ဘာသာရပ်များတွင် Industrial Placement အစီအစဉ်ပါဝင်သည့် ဘာသာရပ်များကိုထည့်သွင်းသင်ကြားနိုင်မှု','B12','','','16 of 56 subjects',''),(8,1,'8','ကျောင်းသူ/ ကျောင်းသားများ အတွက် Internship Program များစီစဉ်ဆောင်ရွက်နိုင်မှု (ဝန်ကြီးဌာနများ/ ပြင်ပကုမ္ပဏီများနှင့် ချိတ်ဆက်သွားရောက်နိုင်မှုအား ခွဲခြားရေးသားပေးပါရန်)','B13','','','ကုမ္ပဏီများသို့ - ၂၄၉',''),(9,1,'9','LMS အသုံးပြုနိုင်ရန် Digital Content များဖန်တီးနိုင်မှု','B14','','','15',''),(10,1,'10','ပြည်ပမှ Educational Digital Content များအသုံးပြုနိုင်ရန် ဆောင်ရွက်နိုင်မှုအခြေအနေ','B15','','','no',''),(11,1,'11','တက္ကသိုလ်များတွင် ဖိုင်ဘာကွန်ရက်၊ အင်တာနက်ကွန်ရက် ချိတ်ဆက်ပြီးစီးမှု အခြေအနေ','B17','','','IP Star, Fiber (2015) ',''),(12,1,'12','တက္ကသိုလ်များတွင် ဒီဂျစ်တယ် အခြေခံအဆောက်အဦများ တည်ထောင်နိုင်မှု အခြေအနေ\n(4G အသုံးချမှုနှင့် Mobile/ Broadband၊ Cloud Computing နှင့် Data Center အခြေခံအဆောက်အဦများ)','B18','','','-',''),(13,1,'13','နည်းပညာအသုံးပြုမှု တီထွင်ဖန်တီးနိုင်မှုနှင့် စွန့်ဦးတီထွင်နိုင်မှု စွမ်းရည်